from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row}
    # Find background cells that cannot reach the edge without crossing a non-background cell.
    bg = min(colors, key=lambda c: sum(row.count(c) for row in grid))
    seen = set()
    q = deque()
    for r in range(h):
        for c in range(w):
            if (r in (0, h - 1) or c in (0, w - 1)) and grid[r][c] == bg:
                seen.add((r, c)); q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and grid[nr][nc] == bg:
                seen.add((nr,nc)); q.append((nr,nc))
    out = [row[:] for row in grid]
    fill = next((v for v in range(10) if v not in colors), None)
    if fill is None:
        fill = 4
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg and (r,c) not in seen:
                out[r][c] = fill
    return out
